import sys

def min_paint_cost(n, m, black_rectangles):
    points = [[] for _ in range(n**2+1)]
    top_left, bottom_right = set(), set()

    for x1, y1, x2, y2 in black_rectangles:
        points[x1+y1].append((x1, y1))
        top_left.add((min(x1, x2), min(y1, y2)))
        bottom_right.add((max(x1, x2), max(y1, y2)))

    dp = [[float('inf')] * (n**2+1) for _ in range(2)]

    for mask in range(1, n**2+1):
        for memo in range(2):
            if mask in top_left:
                points[mask] = [(-1, -1)]
                dp[memo][mask] = min(dp[memo][mask-1]+mask, dp[memo][mask-1]+mask)
            elif mask == n**2:
                dp[memo][mask] = min(dp[memo][mask-1], stack_trace(mask, bottom_right, memo))
            else:
                points[mask] = sorted(points[mask-1]+points[mask])
                for x, y in points[mask]:
                    memo = 1 if memo == 0 else 0
                    dp[memo][mask] = min(dp[memo][mask-1]+stack_trace(mask, points[mask], memo), dp[memo][mask-1]+i_path_search(n**2, mask-x, memo))

    return dp[-1][-1]

def stack_trace(mask, stack, memo):
    res = 0
    while res < mask and stack[-1] < memo:
        res += stack_trace(stack.pop(), stack, memo)
    return res

def i_path_search(target, cur, memo):
    if cur == target and memo == 0:
        return 0
    elif cur == target and memo == 1:
        return 1
    memo = 1 if memo == 0 else 0 
    return dp[1-memo][target-mask] + stack_trace(target-mask, [stack_trace([value for value in stack if value < memo])], memo)

n, m = map(int, input().split())
