    """
    AC: 0ms, 12.1mb
    """
    # Filter out character species and classes that can be unlocked without a guide
    species_to_unlock = {i for i, x in enumerate(a) if x > 0}
    class_to_unlock = {j for j, x in enumerate(b) if x > 0}

    # Create a 2D array where a[i][j] = c[i][j] + k
    # This is the array that will be built incrementally
    target = [[0] * m for _ in range(n)]

    # Maintain a min-heap by columns (species) for pending checks
    pending_species = list(range(n))
    for species, species_points in enumerate(c):
        if species_to_unlock & set(pending_species):
            for class_to_unlock_criteria, c_class in enumerate(target):
                if class_to_unlock & set(pending_species): 
                    max_untrained = c_class[species_to_unlock.pop()]
                else:
                    max_untrained = 0
                max_target = max([c_class[i] for i in range(m)] + target[species_to_unlock])
                if max_untrained > 0:                    
                    heappush(target[species], max(min(max_untrained, k), max_untrained * 2))
                elif max_target < k:
                    heappush(target[species], max_target + k)
                elif max_target == k and species_points:
                    heappush(target[species], species_points)
                else:  # if max_target == k and max_untrained == 0
                    heappush(target[species], target[species][-1])

    result = 0
    while pending_species:
        species = heappop(pending_species)
        for class_to_unlock_criteria, c_class in enumerate(target):
            if class_to_unlock & set(pending_species): 
                max_untrained = c_class[class_to_unlock.pop()]
            else:
                max_untrained = 0
            if species in species_to_unlock:                
                heappush(target[species], max(min(max_untrained, k), max_untrained * 2))
            elif not target[species]:
