import math

def has_large_bitmask(number, mask):
    while number != 0:
        if number & 1 == 1:
            return True
        number >>= 1
    return False

def find_permutations(N):
    if N == 1 or has_large_bitmask(N, N):
        return ("NO", None, None)
    elif N % 2 == 0:
        perm1 = [i for i in range(1, N + 1)]
        perm2 = [i for i in range(1, N + 1)]
        if has_large_bitmask(N, N - 1):
            for i in range(1, N + 1):
                if (i & N - 1) != 0:
                    perm1[i - 1], perm2[N - 1] = perm2[N - 1], perm1[i - 1]
            return ("YES", "".join(map(str, perm1)), "".join(map(str, perm2)))
        elif has_large_bitmask(N, N - 2):
            for i in range(1, N + 1):
                if (i & (N - 2)) != 0:
                    perm1[i - 1], perm2[N - 1] = perm2[N - 1], perm1[i - 1]
            return ("YES", "".join(map(str, perm1)), "".join(map(str, perm2)))
        else:
            return ("NO", None, None)
    else:
        perm1 = [i for i in range(1, N + 1)]
        if has_large_bitmask(N, N - 2):
            perm2 = [N] + [i for i in range(N - 1, 0, -1)]
        elif has_large_bitmask(N, N - 3):
            perm2 = [N - 1] + [i for i in range(N - 2, 0, -1)]
        else:
            return ("NO", None, None)
        if has_large_bitmask(N // 2, 1):
            for i in range(1, N + 1):
                if (i & N // 2) != 0 and has_large_bitmask(2 * N, perm1[i - 1] + perm2[i - 1]):
                    perm1[i - 1] += perm2[i - 1]
                    perm2[i - 1] = 0
        else:
            for i in range(1, N + 1):
                if (i & N // 2) != 0 and not has_large_bitmask(2 * N, perm1[i - 1] + perm2[N - 1 - i]):
                    perm1[perm1[i - 1] + perm2[N - 1 - i] - 1] += perm1[i - 1] + perm2[N - 1 - i]
                    perm1[i - 1] = 0
                    perm2[N - 1 - i] = 0
        return ("YES", "".join(map(str, perm1)), "".join(map(str, perm2)))

