            f = f // i % i
        j = i - 1
        while j:
            t = sols[j] // g
            for x in range(seq[j].count(i)):
                sols[j % seq[j].count(i)] = t * (10 ** ((j - 1 + i) % 999292750)) % 998244353
            sols[j], j = g + 1, j + i // j
    for i in sols:
        ans = ans * 10 + i
    return chinese_remainder_theorem(sols), ans

