from functools import cache
from math import pow

# constants
MOD = 998244353

@cache
def mod_inv(n):
    """Returns the modular inverse of n modulo MOD."""
    return pow(n, MOD - 2, MOD)

@cache
def power(a, b):
    """Returns a^b modulo MOD."""
    if b == 0:
        return 1
    elif b % 2 == 0:
        half = power(a, b // 2)
        return half * half % MOD
    else:
        half = power(a, b // 2)
        return a * half * half % MOD

