def max_rb_prefix_count(seqs):
    dp = defaultdict(int)
    total_length = sum(len(s) for s in seqs)

    for i in range(1, total_length + 1):
        for s in seqs:
            prefix = s[:i]
            if is_rb_sequence(prefix):
                dp[i] = max(dp[i], dp.get(i - len(s), 0) + 1)

