from collections import defaultdict

def count_groups(connected_groups, student_count, group_count):
    if student_count <= group_count:
        return 0
    visited = [False] * group_count
    connected_students = defaultdict(list)
    for start, end in connected_groups:
        if student_count != len(student_count[start]) and student_count != len(student_count[end]):
            return 0

        connected_students[start].append(end)
        connected_students[end].append(start)

    for i, group in enumerate(student_count):
        for j, student in enumerate(group):
            start = connected_students[student][i]
            forest = 0
            cur = i
            while start != cur:
                visited[start] = True
                cur = connected_groups[start][i]
                for child in connected_groups[cur]:
                    if not visited[child]:
                        forest += 1
                        start = child
            connected_students[student].append(forest)

    for student_count in student_count:
        if not 0 in student_count or any(v % 2 != 0 for v in student_count):
            return 0
    return 1

def total_groups(n, m, k, student_count, directed):
    if m == 0:
        return count_groups(directed, student_count, k)
    group_count = 0
    for i in range(1, k + 1):
        group_constraints = [
            (-i for _ in range(j % 2) for j in range(i - 1, -1, -1)),
            (i - 1 for _ in range(j % 2) for j in range(i))
        ]
        per_constraints = [
            (-i for _ in range(j % 2) for j in range(i))
            if k - i == i * (len(student_count[i:]) + 1) else
            (i for _ in range(j % 2) for j in range(i))
        ]
        group_count += ((count_groups(group_constraints, student_count, k) 
                         + count_groups(per_constraints, student_count, k)) % 1000000007)
    return group_count % 1000000007
