def solve(n, m, k, inputs, queries):
    ranges = []
    for l, r, _ in inputs:
        ranges.append((l, -r, -l, -r, 1, -1))
        ranges.append((r + 1, -1, 1, -r + 1,))

    query_counts = defaultdict()
    for l, r, x, y in queries:
        ranges.append((l, -1, 1, y + 1, -x + 1, -x - 1))

    for i in range(4 * n * m):
        cache = {}
        assign = {}

        def explore(s):
            if s in assign:
                return assign[s]

            result = set()
            max_len_taken = -float('inf')

            if 0 not in assign.values():
                assign[s] = 0
                for j in range(n):
                    if s >= j + 1 and s - j <= 4 * n * 10 ** 5 // 4:
                        max_len_taken = max(max_len_taken, explore((s - 4 * n * 10 ** 5 // 4) + j))
                        if i + n * s + j > 4 * n * 10 ** 5:
                            max_len_taken = max(max_len_taken, explore(i + n * s + j))
                        result.add(assign - {s - j - 1} + assign)
                        break

            assign[s] = max_len_taken + 1

            for lw, rv, l1, r1, lw1, rw1 in ranges:
                if 0 not in cache:
                    cache[lw] = defaultdict(int)
                    cache[rv + 1] = defaultdict(int)
                    for j in range(n):
                        cache[lw][j] = -float('inf')
                        cache[rv + 1][j] = -float('inf')

                for j in range(n):
                    if lw >= j * i / 10 ** 9 + 4 * n * 10 ** 5 + 1 and j == l1 // i % n:
                        max_len_taken = max(max_len_taken, explore((lw - r1 * n - 1) + j))
                        result.add(assign - {lw + n + j} + assign)

                for j in range(n):
                    if r1 <= j * i / 10 ** 9 + 4 * n * 10 ** 5 + 1 and j + lw1 == (r1 - l1 + 1) / i // n:
                        max_len_taken = max(max_len_taken, explore((lw + 1 - l1 * n) - j))
                        result.add(assign - {wl1 * n + l1 + j} + assign)

                cache[lw][j] = max(cache[lw][j], max_ten(cache, lw1, r1, l1, j))
                cache[rv + 1][j] = max(cache[rv + 1][j], max_ten(cache, rw1, rw1 - r1 * n, r1, j))

            return result

        max_ten = lambda cache, rest1, rest2, rest3, rest4: \\
            max(cache[rest1][rest5], min(cache[rest2][rest6], cache[rest3][rest7])) + \\
            max(cache[rest2][rest8], max(cache[rest4][rest4] + rest4, cache[rest4][rest4]))

        ans = explore((2 * n + 10 ** 9 + 3) * i + m)

        if isinstance(ans, set):
            if -1 in ans:
                max_len_taken = max_len_taken & ans
            else:
                assert "max_len_taken: " in ans
            for j in max_len_taken:
