                outside_counts[outside_group] += len(students.intersection(group_to_students[outside_group]))

    # For each pair of groups, if they have students outside both groups, they can be selected
    valid_pairs = 0
    for starting_group in group_to_students:
        for ending_group in group_to_students:
            if starting_group != ending_group:
                outside_sum = outside_counts[starting_group] + outside_counts[ending_group]
                if outside_sum >= 2:
                    valid_pairs += 1
    return valid_pairs

