def generate_lines(input_points: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    lines = set()
    for i in range(len(input_points)):
        for j in range(i + 1, len(input_points)):
            lines.add((input_points[i][0] - input_points[j][0], input_points[i][1] - input_points[j][1]))
    return list(lines)

def is_symmetric_multiset(line: Tuple[int, int], points: List[Tuple[int, int]]) -> bool:
    if line[0] == 0:  # vertical line
        return sorted([points[i][0] * line[1] for i in range(len(points))]) == sorted([-pts[0] for pts in points])
    if line[1] == 0:  # horizontal line
        return sorted([points[i][1] * line[0] for i in range(len(points))]) == sorted([-pts[1] for pts in points])
    return sorted([points[i][0] * line[1] + points[i][1] * line[0] for i in range(len(points))]) == sorted([-pts[0] for pts in points])

def count_good_lines(points: List[Tuple[int, int]]) -> int:
    lines = generate_lines(points)
    count = 0
    for line in lines:
        if is_symmetric_multiset(line, points):
            count += 1
    return count // 2  # Each good line is counted twice, so we divide by 2

