import heapq

def kth_mod(array, k):
    return array[k-1]

class TrickTrick:
    def __init__(self, initial_set, changes):
        self.initial_set = initial_set
        self.changes = changes
        self.need_changes = []
        self.max_size = 0
        self.unsuitable_count = set()
        self.precision = 16

    def get_initial_unsuitable_count(self):
        actual_counts = []
        for i in range(len(self.initial_set)):
            actual_counts.append(min(i + 1, kth_mod(self.initial_set, i + 1)))
        return sorted(actual_counts, reverse=True)[:len(self.initial_set) - 1]

    def check_new_set(self, a, b_or_x):
        if a == 'add':
            x = int(b_or_x)
            if x not in self.need_changes:
                heapq.heappush(self.need_changes, x)
            if len(self.need_changes) == 1:
                self.max_size = self.need_changes[0]
        elif a == 'remove':
            x = int(b_or_x)
        else:
            raise ValueError("Invalid operation type")
        assert x in self.need_changes

    def solve(self, changes):
        self.need_changes.clear()
        for change in changes:
            if change[0] == 1:
                self.check_new_set('add', change[1])
            elif change[0] == 2:
                self.check_new_set('remove', change[1])
            else:
                raise ValueError("Invalid change type")
        unsuitable_count = self.get_initial_unsuitable_count()
        for i in range(len(changes) + 1):
            unsuitable_count = filter(lambda x: x < kth_mod(unsuitable_count, i), unsuitable_count)
            if i < len(self.need_changes) // 2:
                unsuitable_count = filter(lambda x: x > kth_mod(unsuitable_count, i + 1), unsuitable_count)
            if unsuitable_count and unsuitable_count[-1] != unsuitable_count[-2]:
                self.need_changes &= unsuitable_count
                assert len(self.need_changes) % 2 == 1
        return len(self.need_changes)


# Example usage:
