from collections import defaultdict
from math import gcd
from typing import List, Tuple

def modular_inverse(a: int, m: int) -> int:
    """Solve the modular equation ax ≡ 1 (mod m)"""
    for i in range(m):
        if (a * i) % m == 1:
            return i
    assert False

def gcd_extended(a: int, b: int) -> Tuple[int, int, int]:
    """Compute gcd(a, b) and coefficients x, y of Bezout's identity ax + by = gcd(a, b)."""
    if a == 0:
        return (b, 0, 1)
    else:
        g, x, y = gcd_extended(b % a, a)
        return (g, y - (b // a) * x, x)

class TaskTree:
    def __init__(self):
        self.exact_impossibilities = defaultdict(list)  # Indices of tasks that are impossible at each time
        self.undone_upto_current_time = defaultdict(int)  # Count of undone tasks up to this time

    def time_travel(self, task_index: int, new_time: int) -> int:
        # Check if Okabe needs to travel to a different time
        if self.time_travel_over_minimum or self.time_travel_over_maximum:
            return 0  # He already completed all tasks by this point
        undones = set(self.undone_upto_current_time.keys())
        if task_index not in undones and new_time not in undones:
            if new_time >= self.calls:
                time_travel_count = (self.calls - new_time) * 2
            else:
                time_travel_count = self.calls
            self.calls = new_time + 1
            self.undone_upto_current_time[new_time] = 0

        # Return the number of times he will travel before all the tasks in s become complete
        return self.time_travel(s) + time_travel_count

def compute(durations: List[Tuple[int, int]], swimming_time: int, swimmer_tasks: List[int]) -> int:
    time_travel_tree = TaskTree()
    calls = 0
    changed = False
    time_travel_tree.calls = 0
    dedup = set()

    for time, task in durations:
        if task not in dedup and (time - task < swimming_time):
            time_travel_tree.undone_upto_current_time[time] = 0
        time_travel_tree.calls = time + 1
        time_travel_tree.undone_upto_current_time[time] += 1
        dedup.add(task)
        time_travel_tree.exact_impossibilities[task].append(time)

    longest_chain = gcd_extended(len(durations), time_travel_tree.calls)[0]
    if longest_chain == 1:
        # If there's only one task, it travels once.
        return 1
    elif len(time_travel_tree.exact_impossibilities) < longest_chain:
        # The len of impossibilities chain >= longest_chain, make sure both can fit into the solution
        if len(time_travel_tree.exact_impossibilities) < longest_chain or swimming_time > time_travel_tree.calls:
            # If exact limitation < longest even if geometric, or swimming time is higher than total calls
            return longest_chain
        else:
            # exact_chain first. Then we always make each posit + 1 further + 1 further + related tasks to avoid missed those task
            return len(time_travel_tree.exact_impossibilities[0]) + len(time_travel_tree.exact_impossibilities[1])
    else:
        # exact_chain first, all subchain travel further later. Finish it by number of chain sequence to avoid missed those task
        tasks_overlapping_chain = [t + 1 for t in dedup if t * longest_chain <= time_travel_tree.calls]
        return sum(tasks_overlapping_chain) % 1000000007
