                    S.pop(S.index(min(S)))

        applicable_size_sum = sum(element - x for element in S if element > x)
        candidates = [sum(S) + 1]
        for element in S:
            candidates.append(sum(S) + element - x)

        unmeasured_size_indices = [1, 3, 5, 7, 9, 11]
        while len(candidates) < applicable_size_sum:
            candidates[unmeasured_size_indices.pop(0)] += S.pop(S.index(min(S)))

        differences = sorted(list(map(itemgetter(1), filter(is_all_elements_above_upper_bound, zip(candidates, S)))))

        if differences:
            findings = [abs(sum(S) - x), 0]
            for i in unmeasured_size_indices:
                findings[i] = 0
                if find_matching_with_upper_bound(x, S, differences[i]):
                    for j in [i - 1, i + 1]:
                        if 0 <= j < len(candidates) and difference := abs(sum(S) - x):
                            findings[j] = difference
            to_omit = sorted(candidates[::2])[:int(len(candidates)//2)]
            to_add = sorted(candidates[1::2])[:int(len(candidates)//2)]
            for widget in to_add:
                candidates[unmeasured_size_indices[i + 1]] = widget
                for difference in findings[unmeasured_size_indices[i + 1] + 2:]:
                    candidates[i + 1 + (differences.index(difference)) * 2] -= difference
                differences = sorted(difference, reverse=True) + differences

    return candidates
