from collections import defaultdict

def count_groups_without_acquaintances():
    import sys
    input = sys.stdin.read

    n, m, k, *groups = map(int, input().split())
    known_pairs = defaultdict(list)
    for i in range(m):
        a, b = map(int, input().split())
        known_pairs[a].append(b)
        known_pairs[b].append(a)

    group_to_x = defaultdict(list)
    group_to_y = defaultdict(set)

    find2 = set()  # Not group numbers between 1 and k
    for group in range(1, k):
        for x in groups[group - 1]:
            known_pairs[x].sort()
            for i, y in enumerate(known_pairs[x]):
                need = True
                cur = y
                found = set()  # Not group numbers before current
                while found | group_to_x[cur] | find2:
                    try:
                        cur = group_to_x[cur].pop()  # Find it in a known group
                    except KeyError:
                        need = False  # Not found
                else:
                    group_to_x[cur].remove(x)  # Remove and finish current group
                group_to_y[x].update(y)  # Remember it for later

                if x < y and not group in find2:  # In case of disjoint sets
                    found.add(x)
                    find2.add(group)

    disj_pairs = sum([len(k) - 1 for k in group_to_x.values()])
    already_done, c_disj_pairs = {0}, 0

    members = set()
    for k in sorted(group_to_x.keys(), key=lambda x: len(group_to_x[x])):
        if k not in find2:
            members |= set(group_to_y[k])
        elif k - 1 not in find2:
            members |= set(group_to_x[k-1])

    for num in members:
        if len(groups[-1] & group_to_x[num]):
            c_disj_pairs += 1

    return len(members) * (len(members) - 1) // 2 - sum(c_disj_pairs for c_disj_pairs in already_done)  

print(count_groups_without_acquaintances())
