from collections import defaultdict

def get_segment_info(segment, segments, index):
    segments_info = {}.fromkeys(range(max(segment[0] - 1, 0), segment[1]))
    for idx in range(index):
        if segment[0] <= segments[idx][1] <= segment[1]:
            segments_info[idx] = segments[idx]
    return segments_info

def solve_queries():
    n, m, k = map(int, input().split())
    segments = []
    query_info = []

    # Store segments information
    for _ in range(k):
        l, r, index = map(int, input().split())
        segment = [l, r, index]
        segments.append(segment)
        segments_info = get_segment_info(segment, segments, len(segments) - 1)

    # Store queries information
    for _ in range(m):
        a, b, x, y = map(int, input().split())
        q_info = [a, b, x, y]
        query_info.append(q_info)

    while query_info:
        segment_queries, query_info = segments_info, []
        for q in segment_queries:
            for _ in range(q[1] - q[0] + 1):
                q[1] += 1
                if q[1] > len(segments):
                    break
                if q[1] in segments[q[2]]:
                    query_info.append(q[1])
                    break

                if q[2] == n:
                    query_info.append(q[1])
                    break

        for q in query_info:
            print(' '.join(map(str, [q+1, q+2, q+3, q+4])))
            print('Size: ', input().split())
            print('Query answered: ', end='')
            for i in range(q-1):
                print(input())
            print(' '*12)
        query_info.clear()

solve_queries()
