from collections import deque

def is_rbs(sequence):
    stack = deque()
    for char in sequence:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

def rearrange_and_count_brackets(n: int, sequences: list):
    total_prefixes_rbs = 0
    for sequence in sequences:
        reverse_sequence = sequence[::-1]
        if reverse_sequence == '(' + sequence[::-1] + ')':
            total_prefixes_rbs += 1
    permutations = len(sequences) * (len(sequences) - 1) // 2 + len(sequences) * len(sequences) // 2
    return permutations // total_prefixes_rbs

n = int(input())
sequences = [input() for _ in range(n)]
print(rearrange_and_count_brackets(n, sequences))
